<script setup lang="ts">import {readings} from '~/data/expanded';const index=ref(0);const pinyin=ref(true);const selected=ref('');const item=computed(()=>readings[index.value]);const speak=()=>speechSynthesis.speak(new SpeechSynthesisUtterance(item.value.text));const select=(token:string)=>{selected.value=token}</script>
<template><section><div class="page-title"><span class="eyebrow">LEITURA GRADUADA · {{item.level}}</span><h1>{{item.title}}</h1><p class="muted">Texto {{index+1}} de {{readings.length}} · toque em uma palavra para explorar.</p></div><div class="card" style="max-width:850px"><div style="display:flex;gap:10px;margin-bottom:25px"><button class="button" @click="pinyin=!pinyin">{{pinyin?'Ocultar':'Mostrar'}} Pinyin</button><button class="button" @click="speak">🔊 Ouvir texto</button></div><div style="font-family:'Noto Sans SC';font-size:32px;line-height:2.1"><button v-for="token in item.tokens" :key="token" @click="select(token)" style="font:inherit;background:none;border:0;color:inherit;cursor:pointer;border-bottom:2px solid #dff3ee">{{token}}</button><br><span v-if="pinyin" class="muted" style="font-family:'DM Sans';font-size:16px">{{item.pinyin}}</span></div><div v-if="selected" class="card" style="background:#f7faf8;margin-top:22px"><b>{{selected}}</b><p class="muted">Toque para consultar o dicionário ou adicionar aos flashcards.</p><NuxtLink to="/characters" class="pill">Abrir dicionário</NuxtLink></div><hr style="border:0;border-top:1px solid var(--line);margin:30px 0"><p class="muted">{{item.translation}}</p><div style="display:flex;justify-content:space-between;margin-top:25px"><button class="button" :disabled="index===0" @click="index--">← Anterior</button><button class="button primary" :disabled="index===readings.length-1" @click="index++">Próximo texto →</button></div></div></section></template>
